def solve():
    S = input().strip()
    n = len(S)
    MOD = 998244353

    # dp[i][j] = number of ways to process first i characters with balance j
    # balance is the difference between open and close parentheses
    max_balance = n  # maximum possible balance
    dp = [[0] * (max_balance + 1) for _ in range(n + 1)]

    # Base case: 0 characters processed, balance 0
    dp[0][0] = 1

    for i in range(n):
        char = S[i]
        for balance in range(max_balance + 1):
            if dp[i][balance] == 0:
                continue

            if char == '(':
                # Must add an opening parenthesis
                if balance < max_balance:
                    dp[i + 1][balance + 1] = (dp[i + 1][balance + 1] + dp[i][balance]) % MOD

            elif char == ')':
                # Must add a closing parenthesis, but only if we have open parentheses
                if balance > 0:
                    dp[i + 1][balance - 1] = (dp[i + 1][balance - 1] + dp[i][balance]) % MOD

            else:  # char == '?'
                # Can choose either '(' or ')'
                if balance < max_balance:
                    dp[i + 1][balance + 1] = (dp[i + 1][balance + 1] + dp[i][balance]) % MOD
                if balance > 0:
                    dp[i + 1][balance - 1] = (dp[i + 1][balance - 1] + dp[i][balance]) % MOD

    # Answer is the number of ways to process all characters with balance 0
    return dp[n][0]

